package com.qiban.companion;
import android.content.Context;
import android.media.*;
import android.os.*;
import android.speech.tts.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import org.json.*;

final class SpeechPlayer implements AutoCloseable {
    private final Context context;private final ArchiveStore store;private final PackLibrary packs;private final NetworkBroker network;
    private final java.util.function.Consumer<JSONObject> events;private final ExecutorService worker=Executors.newSingleThreadExecutor();
    private final Handler main=new Handler(Looper.getMainLooper());private final AtomicInteger generation=new AtomicInteger();private volatile AtomicBoolean cancellation=new AtomicBoolean();
    private volatile AudioTrack track;private volatile MediaPlayer media;private final TextToSpeech system;private final CountDownLatch systemReady=new CountDownLatch(1);private volatile int systemStatus=-1;
    private NeuralVoice neural;private String neuralKey="";private final Map<String,String> japanese=new ConcurrentHashMap<>();
    private volatile boolean active=false;
    boolean isBusy(){return active;}
    SpeechPlayer(Context context,ArchiveStore store,PackLibrary packs,NetworkBroker network,java.util.function.Consumer<JSONObject> events){this.context=context;this.store=store;this.packs=packs;this.network=network;this.events=events;system=new TextToSpeech(context,status->{systemStatus=status;systemReady.countDown();});}
    String text(JSONObject body)throws Exception {JSONObject speech=store.settings().getJSONObject("speech");String zh=body.isNull("spokenChinese")?SpokenDialogue.dialogue(body.optString("text")):SpokenDialogue.explicit(body.optString("spokenChinese"));if(zh.isEmpty())return "";if(speech.optString("language","zh").equals("ja")){String ja=SpokenDialogue.explicit(body.optString("spokenJapanese"));if(ja.isEmpty())throw new IOException("这条消息尚无日文台词。");return ja;}return zh;}
    JSONObject speak(JSONObject input,Runnable actualStart)throws Exception {return speak(input,actualStart,null);}
    JSONObject preview(JSONObject input,JSONObject draft)throws Exception{return speak(input,()->{},draft);}
    private JSONObject speak(JSONObject input,Runnable actualStart,JSONObject draft)throws Exception {
        JSONObject global=store.settings().getJSONObject("speech"),speech=draft==null?global:draft;if(!global.optBoolean("enabled",true))return new JSONObject().put("skipped",true);
        if(!input.optBoolean("automatic"))stop();int ticket=generation.get();String zh=input.isNull("spokenChinese")?SpokenDialogue.dialogue(input.optString("text")):SpokenDialogue.explicit(input.optString("spokenChinese"));if(zh.isEmpty())return new JSONObject().put("skipped",true).put("spokenChinese","");String ja=SpokenDialogue.explicit(input.optString("spokenJapanese"));
        if(speech.optString("language","zh").equals("ja")&&ja.isEmpty()){ja=japanese.getOrDefault(zh,"");if(ja.isEmpty()){String translated=NetworkBroker.reply(network.complete(new JSONArray().put(new JSONObject().put("role","system").put("content","只将给定中文实际台词翻译成自然日语，不添加动作、心理或解释。只输出译文。")).put(new JSONObject().put("role","user").put("content",zh.substring(0,Math.min(1500,zh.length())))),null));ja=SpokenDialogue.explicit(translated);if(ja.isEmpty())throw new IOException("接口未返回日文台词。");japanese.put(zh,ja);}}
        if(ticket!=generation.get())return new JSONObject().put("skipped",true);String line=speech.optString("language","zh").equals("ja")?ja:zh,id=input.optString("id",UUID.randomUUID().toString());
        worker.execute(()->{if(ticket!=generation.get())return;AtomicBoolean cancelled=new AtomicBoolean();cancellation=cancelled;active=true;try{event("speech",id,true,"正在准备语音");JSONObject remote=network.service("tts");boolean started=false;for(String part:SpokenDialogue.sentences(line)){if(ticket!=generation.get()||cancelled.get())break;Runnable begin=started?()->{}:actualStart;started=true;if(remote!=null&&remote.optBoolean("enabled")){byte[] wav=network.speech(remote,part,(float)speech.optDouble("speed",1));if(ticket!=generation.get())break;playWav(wav,speech,id,cancelled,begin);}else if(!speech.optString("voiceID","system.zh").startsWith("system.")){String language=speech.optString("language","zh"),key=language+"|"+new File(packs.voice,"manifest.json").lastModified()+"|"+speech.optString("computeMode","automatic");if(neural==null||!neuralKey.equals(key)){neural=null;neural=new NeuralVoice(packs.voice,language,!speech.optString("computeMode","automatic").equals("cpu"),Math.min(4,Math.max(2,Runtime.getRuntime().availableProcessors()/2)));neuralKey=key;}float[] audio=neural.synthesize(part,(float)speech.optDouble("speed",1),cancelled);if(ticket!=generation.get())break;playPCM(audio,speech,id,cancelled,begin);}else playSystem(part,speech,id,cancelled,begin);}}catch(Exception|LinkageError e){if(ticket==generation.get())event("speech",id,false,"语音失败："+e.getMessage());}finally{active=false;if(ticket==generation.get()){event("speech",id,false,"");level(0);}}});
        return new JSONObject().put("started",true).put("spokenChinese",zh).put("spokenJapanese",ja);
    }
    private void event(String type,String id,boolean busy,String status){try{events.accept(new JSONObject().put("type",type).put("id",id).put("busy",busy).put("status",status));}catch(JSONException ignored){}}
    private void level(float value){try{events.accept(new JSONObject().put("type","level").put("value",value));}catch(JSONException ignored){}}
    private void playPCM(float[] samples,JSONObject speech,String id,AtomicBoolean cancelled,Runnable begin)throws Exception {int buffer=Math.max(16384,AudioTrack.getMinBufferSize(32000,AudioFormat.CHANNEL_OUT_MONO,AudioFormat.ENCODING_PCM_FLOAT));AudioTrack player=new AudioTrack.Builder().setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_SPEECH).build()).setAudioFormat(new AudioFormat.Builder().setSampleRate(32000).setChannelMask(AudioFormat.CHANNEL_OUT_MONO).setEncoding(AudioFormat.ENCODING_PCM_FLOAT).build()).setBufferSizeInBytes(buffer).setTransferMode(AudioTrack.MODE_STREAM).build();track=player;try{player.setVolume((float)speech.optDouble("volume",1));int first=Math.min(512,samples.length);player.write(samples,0,first,AudioTrack.WRITE_NON_BLOCKING);if(cancelled.get())return;player.play();begin.run();event("speech",id,true,"正在朗读");for(int offset=first;offset<samples.length&&!cancelled.get();){int n=Math.min(3200,samples.length-offset),written=player.write(samples,offset,n,AudioTrack.WRITE_BLOCKING);if(written<0)throw new IOException("音频播放中断。");double energy=0;for(int i=offset;i<offset+written;i++)energy+=samples[i]*samples[i];level((float)Math.min(1,Math.sqrt(energy/Math.max(1,written))*5));offset+=written;}while(!cancelled.get()&&Integer.toUnsignedLong(player.getPlaybackHeadPosition())<samples.length)Thread.sleep(20);}finally{track=null;player.release();level(0);}}
    private void playWav(byte[] wav,JSONObject speech,String id,AtomicBoolean cancelled,Runnable begin)throws Exception {if(wav.length<44||wav.length>12*1024*1024||!new String(wav,0,4,java.nio.charset.StandardCharsets.US_ASCII).equals("RIFF")||!new String(wav,8,4,java.nio.charset.StandardCharsets.US_ASCII).equals("WAVE"))throw new IOException("云端 TTS 未返回有效 WAV。");File file=File.createTempFile("qiban-speech-",".wav",context.getCacheDir());FilesSupport.atomic(file,wav);MediaPlayer player=new MediaPlayer();media=player;CountDownLatch done=new CountDownLatch(1);try{player.setDataSource(file.getPath());player.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_SPEECH).build());player.setOnCompletionListener(p->done.countDown());player.setOnErrorListener((p,w,e)->{done.countDown();return true;});player.prepare();if(player.getDuration()>120000)throw new IOException("单段语音超过120秒。");float volume=(float)speech.optDouble("volume",1);player.setVolume(volume,volume);if(cancelled.get())return;player.start();begin.run();event("speech",id,true,"正在朗读");level(.35f);while(!cancelled.get()&&!done.await(100,TimeUnit.MILLISECONDS)){} }finally{media=null;player.release();file.delete();level(0);}}
    private void playSystem(String text,JSONObject speech,String id,AtomicBoolean cancelled,Runnable begin)throws Exception {if(!systemReady.await(10,TimeUnit.SECONDS)||systemStatus!=TextToSpeech.SUCCESS)throw new IOException("本机没有可用的系统语音服务，请安装音色或导入 .qvoice。");Locale language=speech.optString("language","zh").equals("ja")?Locale.JAPANESE:Locale.SIMPLIFIED_CHINESE;int result=system.setLanguage(language);if(result<0)throw new IOException("系统未安装所选语言音色，请在安卓语音设置中下载。");Set<Voice> voices=system.getVoices();Voice offline=null;if(voices!=null)for(Voice v:voices)if(v.getLocale().getLanguage().equals(language.getLanguage())&&!v.isNetworkConnectionRequired()&&!v.getFeatures().contains(TextToSpeech.Engine.KEY_FEATURE_NOT_INSTALLED)){offline=v;if(v.equals(system.getVoice()))break;}if(offline==null||system.setVoice(offline)<0)throw new IOException("系统未安装本机离线音色，请下载对应语言或导入 .qvoice。");system.setSpeechRate((float)speech.optDouble("speed",1));CountDownLatch done=new CountDownLatch(1);String utterance=UUID.randomUUID().toString();system.setOnUtteranceProgressListener(new UtteranceProgressListener(){public void onStart(String u){if(!u.equals(utterance)||cancelled.get())return;begin.run();event("speech",id,true,"正在朗读");level(.35f);}public void onDone(String u){if(u.equals(utterance))done.countDown();}public void onError(String u){if(u.equals(utterance))done.countDown();}});Bundle params=new Bundle();params.putFloat(TextToSpeech.Engine.KEY_PARAM_VOLUME,(float)speech.optDouble("volume",1));main.post(()->{if(!cancelled.get())system.speak(text,TextToSpeech.QUEUE_FLUSH,params,utterance);});while(!cancelled.get()&&!done.await(100,TimeUnit.MILLISECONDS)){}level(0);}
    void previewWav(byte[] wav)throws Exception {stop();JSONObject preferences=store.settings().getJSONObject("speech");int ticket=generation.get();worker.execute(()->{if(ticket!=generation.get())return;AtomicBoolean cancelled=new AtomicBoolean();cancellation=cancelled;active=true;try{playWav(wav,preferences,"preview",cancelled,()->{});}catch(Exception error){event("speech","preview",false,error.getMessage());}finally{active=false;event("speech","preview",false,"");}});}
    void stop(){active=false;generation.incrementAndGet();cancellation.set(true);system.stop();AudioTrack t=track;if(t!=null)try{t.pause();t.flush();}catch(IllegalStateException ignored){}MediaPlayer m=media;if(m!=null)try{m.pause();}catch(IllegalStateException ignored){}level(0);event("speech","",false,"");}
    void invalidateVoice(){stop();worker.execute(()->{neural=null;neuralKey="";});}
    public void close(){stop();worker.shutdownNow();system.shutdown();}
}
